$\begin{aligned}
|\mathrm{A}| & =-1,|\mathrm{~B}|=1 \\
\mathrm{~A}^{-1} & =\frac{1}{|\mathrm{~A}|} \operatorname{Adj} \mathrm{A}=\frac{1}{-1}\left[\begin{array}{cc}
1 & -1 \\
-2 & 1
\end{array}\right]^{\mathrm{T}} \\
& =\left[\begin{array}{cc}
-1 & 2 \\
1 & -1
\end{array}\right]
\end{aligned}\begin{aligned}
& \mathrm{B}^{-1}=\frac{1}{|\mathrm{~B}|} \mathrm{Adj}=\frac{1}{1}\left[\begin{array}{cc}
2 & -1 \\
1 & 0
\end{array}\right]^{\mathrm{T}}=\left[\begin{array}{cc}
2 & 1 \\
-1 & 0
\end{array}\right] \\
& \mathrm{B}^{-1} \mathrm{~A}^{-1}=\left[\begin{array}{cc}
2 & 1 \\
-1 & 0
\end{array}\right]\left[\begin{array}{cc}
-1 & 2 \\
1 & -1
\end{array}\right]=\left[\begin{array}{cc}
-1 & 3 \\
1 & -2
\end{array}\right] .
\end{aligned}$
